  subgroup_list <- comp[[celltype]]
  for (subgroup_name in names(subgroup_list)) {
    if (subgroup_name %in% model_features) {
      members <- subgroup_list[[subgroup_name]]
      for (m in members) {
        rows[[length(rows)+1]] <- data.frame(subgroup=subgroup_name, feature=m)
      }
    }
  }
}
